package com.bank.keys;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.logging.Logger;

public class AccountDao {
    private static final Logger log = Logger.getLogger(AccountDao.class.getName());
    private final Connection conn;

    public AccountDao(Connection conn) { this.conn = conn; }

    // Returns true on success; logs the specific constraint that rejected it.
    public boolean insert(String id, String name, String email, String pan, String type) {
        String sql = "INSERT INTO accounts (id, holder_name, email, pan, acct_type, balance) "
                   + "VALUES (?, ?, ?, ?, ?, 0.00)";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, id);
            ps.setString(2, name);
            ps.setString(3, email);   // may be null — unique allows one/none nulls
            ps.setString(4, pan);
            ps.setString(5, type);
            ps.executeUpdate();
            log.info(() -> "Inserted account " + id);
            return true;
        } catch (SQLException e) {
            // SQLState 23505 = unique_violation (covers PK and UNIQUE in PostgreSQL)
            log.severe("Rejected " + id + ": " + e.getMessage());
            return false;
        }
    }
}
