package com.bank.keys;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class KeyDemo {
    private static final Logger log = Logger.getLogger(KeyDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            AccountDao dao = new AccountDao(conn);

            // 1. Duplicate PRIMARY KEY (SAV2001 already exists) → rejected.
            dao.insert("SAV2001", "Someone Else", "new@example.com", "ZZZZZ0000Z", "SAVINGS");

            // 2. Duplicate UNIQUE email (rajesh's email reused) → rejected.
            dao.insert("SAV2002", "Another Person", "rajesh@example.com", "LMNOP1111Q", "SAVINGS");

            // 3. NULL email is allowed by a UNIQUE column → accepted.
            dao.insert("SAV2003", "Amit Verma", null, "GHIJK2222R", "SAVINGS");

            log.info("PK rejects duplicate identity; UNIQUE rejects duplicate value but allows NULL.");
        }
    }
}
